"""Rescued pipeline: parse the CSV once, build a dict index, O(1) lookups."""
import csv


class ScoreIndex:
    def __init__(self, path):
        with open(path, newline='') as f:
            reader = csv.reader(f)
            header = next(reader)
            idx = header.index('name')
            sidx = header.index('score')
            self._scores = {
                row[idx]: float(row[sidx])
                for row in reader
                if len(row) > max(idx, sidx)
            }

    def score_of(self, name):
        return self._scores.get(name)

    def total(self, names):
        return sum(self._scores.get(n) or 0.0 for n in names)


def total(path, names):
    """Drop-in replacement: same signature as slow_csv.total."""
    return ScoreIndex(path).total(names)

